test('public rate card estimates API-equivalent costs',()=>{assert.equal(estimateTokenCost('gpt-5.6-sol',{input_tokens:1_000_000,cached_tokens:500_000,output_tokens:100_000}).amount,5.75);assert.equal(estimateTokenCost('claude-sonnet-4',{input_tokens:1_000_000,output_tokens:100_000}).amount,4.5);assert.equal(estimateTokenCost('unknown-model',{input_tokens:1_000_000}),null)})

test('ClickUp proposals map to real workflow statuses',()=>{const statuses=[{status:'backlog',type:'open'},{status:'scoping',type:'custom'},{status:'ready for development',type:'custom'},{status:'shipped',type:'done'},{status:'cancelled',type:'closed'}];assert.equal(clickupStatusFor('proposed',statuses),'scoping');assert.equal(clickupStatusFor('approved',statuses),'ready for development');assert.equal(clickupStatusFor('published',statuses),'shipped');assert.equal(clickupStatusFor('rejected',statuses),'cancelled');assert.equal(clickupStatusFor('superseded',statuses),'cancelled')})

test('project ClickUp tags receive stable distinct colors',()=>{const colors=['nationfall','blockrise','atlas','iberis-rh'].map(slug=>defaultProjectTagColor({slug}));assert.equal(new Set(colors).size,colors.length);for(const color of colors)assert.match(color,/^#[0-9a-f]{6}$/)})

test('image transport optimization preserves source identity',async()=>{const source=await sharp({create:{width:3000,height:2000,channels:3,background:'#d4a44f'}}).png().toBuffer(),result=await optimizeImageTransport(source,{path:'proof.png',mime:'image/png'});assert.equal(result.optimized,true);assert.equal(result.mime,'image/webp');assert.equal(result.extension,'.webp');assert.ok(result.bytes<source.length);assert.equal(result.source_bytes,source.length);assert.equal(result.source_sha256,createHash('sha256').update(source).digest('hex'));assert.notEqual(result.sha256,result.source_sha256);const text=Buffer.from('evidence');assert.equal((await optimizeImageTransport(text,{path:'proof.txt',mime:'text/plain'})).buffer,text)})

