test('migration is idempotent and valid',()=>{ assert.equal(migrate(path).migrated,false); const db=new Database(path,{readonly:true}); assert.equal(db.pragma('integrity_check',{simple:true}),'ok'); assert.deepEqual(db.pragma('foreign_key_check'),[]); db.close() })
test('terminal control plane exposes allowlisted providers and persists session lifecycle',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';let response=await fetch(`${origin}/api/terminal/providers`),data=await response.json();assert.equal(response.status,200);assert.equal(data.remote_access,false);const codexProvider=data.providers.find(row=>row.id==='codex');assert.equal(codexProvider.available,true);assert.ok(Array.isArray(codexProvider.models));assert.ok(Array.isArray(codexProvider.capabilities.efforts));assert.ok(codexProvider.capabilities.efforts.includes('medium'));assert.equal(typeof codexProvider.default_effort,'string');response=await fetch(`${origin}/api/terminal/sessions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex',project:'test',title:'Controlled test terminal'})});data=await response.json();delete process.env.ORCHESTRATOR_CODEX_COMMAND;assert.equal(response.status,201,JSON.stringify(data));assert.equal(data.provider,'codex');assert.equal(data.status,'running');assert.match(data.attach_token,/^[a-f0-9]{64}$/);response=await fetch(`${origin}/api/terminal/sessions/${data.uid}/stop`,{method:'POST'});assert.equal(response.status,202);await new Promise(resolve=>setTimeout(resolve,30));response=await fetch(`${origin}/api/terminal/sessions/${data.uid}`);data=await response.json();assert.ok(['stopped','completed','failed'].includes(data.status));response=await fetch(`${origin}/api/terminal/sessions/${data.uid}/transcript`);assert.equal(response.status,200);assert.ok(Array.isArray((await response.json()).chunks))})
test('terminal sessions preserve their objective and pass linkage',async()=>{const objectiveUid=uid();base().prepare("INSERT INTO objectives(uid,project_id,title,status,priority) VALUES(?,(SELECT id FROM projects WHERE slug='test'),'Linked terminal objective','ready',1)").run(objectiveUid);process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/terminal/sessions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex',project:'test',title:'Linked test terminal',objective:objectiveUid,pass:{source:'plan_direct'},context:{gdd_chapter_key:'delivery'}})}),session=await response.json();assert.equal(response.status,201,JSON.stringify(session));assert.equal(session.metadata.objective_uid,objectiveUid);assert.equal(session.metadata.objective_title,'Linked terminal objective');assert.equal(session.metadata.pass_source,'plan_direct');assert.match(session.metadata.pass_uid,/^[a-f0-9-]+$/);assert.equal(session.metadata.gdd_chapter_key,'delivery');response=await fetch(`${origin}/api/projects/test/planning/objectives/${objectiveUid}`);const detail=await response.json();assert.equal(response.status,200,JSON.stringify(detail));assert.equal(detail.sessions.some(row=>row.uid===session.uid),true);assert.equal(detail.summary.sessions,1);response=await fetch(`${origin}/api/terminal/sessions/${session.uid}/attachments`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'context.png',data_url:'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII='})});const attachment=await response.json();assert.equal(response.status,201,JSON.stringify(attachment));assert.equal(attachment.mime,'image/png');assert.equal(existsSync(attachment.path),true);response=await fetch(`${origin}/api/terminal/sessions/${session.uid}/attachments/${attachment.uid}`);assert.equal(response.status,200);assert.equal(response.headers.get('content-type'),'image/png');response=await fetch(`${origin}/api/terminal/sessions/${session.uid}/report`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({summary:'Read-only result ready for human verification.'})});const report=await response.json();assert.equal(response.status,202,JSON.stringify(report));const reportPayload=typeof report.event.payload==='string'?JSON.parse(report.event.payload):report.event.payload;assert.equal(report.verification,'pending');assert.equal(report.session.metadata.report_status,'awaiting_verification');assert.equal(reportPayload.outcome,'reported');assert.equal(reportPayload.verification,'pending');assert.equal(reportPayload.attachments.some(item=>item.uid===attachment.uid),true);assert.equal(report.evidence.length,2);assert.equal(report.evidence.some(item=>item.summary.startsWith('Transcription')),true);response=await fetch(`${origin}/api/projects/test/evidence?objective=${objectiveUid}`);const proofs=await response.json();assert.equal(proofs.length,2);assert.equal(proofs.every(item=>item.pass_ref===session.metadata.pass_uid),true);for(const proof of proofs){response=await fetch(`${origin}/api/evidence/${proof.uid}/verify`,{method:'POST'});assert.equal(response.status,200)}response=await fetch(`${origin}/api/projects/test/passes/${session.metadata.pass_uid}/close`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objective_uid:objectiveUid})});const closure=await response.json();assert.equal(response.status,200,JSON.stringify(closure));assert.equal(closure.closed,true);assert.equal(closure.evidence_count,2);assert.equal(closure.lesson,null);assert.equal(base().prepare('SELECT status FROM objectives WHERE uid=?').get(objectiveUid).status,'proven')}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})

test('an unlinked project session creates a targeted pass when sent to verification',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/terminal/sessions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex',project:'test',title:'Pilot · Newly discovered bounded work'})}),session=await response.json();assert.equal(response.status,201,JSON.stringify(session));assert.equal(session.metadata.objective_uid,null);response=await fetch(`${origin}/api/terminal/sessions/${session.uid}/report`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({summary:'Result ready.'})});const report=await response.json();assert.equal(response.status,202,JSON.stringify(report));assert.match(report.session.metadata.objective_uid,/^[a-f0-9-]+$/);assert.match(report.session.metadata.pass_uid,/^[a-f0-9-]+$/);assert.equal(report.session.metadata.objective_title,'Newly discovered bounded work');assert.ok(report.evidence.length>=1)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})
test('a stopped Orchestrator session resumes the exact native conversation and keeps its links',async()=>{const objectiveUid=uid(),nativeId='123e4567-e89b-12d3-a456-426614174111';base().prepare("INSERT INTO objectives(uid,project_id,title,status,priority) VALUES(?,(SELECT id FROM projects WHERE slug='test'),'Resumable terminal objective','ready',2)").run(objectiveUid);process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/terminal/sessions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex',project:'test',title:'Persistent Orchestrator session',objective:objectiveUid,pass:{uid:'resume-pass',source:'plan_direct'}})}),session=await response.json();await fetch(`${origin}/api/terminal/sessions/${session.uid}/stop`,{method:'POST'});for(let attempt=0;attempt<20;attempt++){await new Promise(resolve=>setTimeout(resolve,25));const state=await(await fetch(`${origin}/api/terminal/sessions/${session.uid}`)).json();if(!state.active)break}const stored=base().prepare('SELECT metadata FROM terminal_sessions WHERE uid=?').get(session.uid),metadata={...JSON.parse(stored.metadata),native_session_id:nativeId};base().prepare('UPDATE terminal_sessions SET metadata=? WHERE uid=?').run(JSON.stringify(metadata),session.uid);response=await fetch(`${origin}/api/terminal/sessions/${session.uid}/resume`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});const resumed=await response.json();assert.equal(response.status,201,JSON.stringify(resumed));assert.equal(resumed.title,session.title);assert.equal(resumed.metadata.resumed_from_uid,session.uid);assert.equal(resumed.metadata.native_session_id,nativeId);assert.equal(resumed.metadata.objective_uid,objectiveUid);assert.equal(resumed.metadata.pass_uid,'resume-pass');assert.deepEqual(resumed.metadata.arguments.slice(0,2),['resume',nativeId]);await fetch(`${origin}/api/terminal/sessions/${resumed.uid}/stop`,{method:'POST'})}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})
test('project reconciliation detects AI sessions and applies only reviewed plan changes',()=>{const repository=join(dir,'reconciliation-project'),memory=join(dir,'reconciliation-memory'),projectUid=uid(),objectiveUid=uid(),sessionId=uid(),stamp=new Date().toISOString();mkdirSync(repository);mkdirSync(memory);base().prepare("INSERT INTO projects(uid,slug,name,description) VALUES(?,?,?,?)").run(projectUid,'reconciliation-project','Reconciliation Project',`Repository: ${repository}`);const projectRow=base().prepare("SELECT * FROM projects WHERE slug='reconciliation-project'").get();writeFileSync(join(memory,`rollout-${sessionId}.jsonl`),`${JSON.stringify({type:'session_meta',timestamp:stamp,payload:{id:sessionId,cwd:repository}})}\n${JSON.stringify({type:'response_item',timestamp:stamp,payload:{type:'message',role:'assistant',phase:'final_answer',content:[{type:'output_text',text:`CHAPITRE: REC42 — Session-discovered objective\nVERDICT : FAIL\nProjet ${repository}`}]}})}\n`);let workspace=reconciliationWorkspace(projectRow,{days:2,memoryRoots:[['codex',memory]]});assert.equal(workspace.sessions.length,1);const discovered=workspace.suggestions.find(row=>row.action==='create_objective'&&row.title.includes('REC42')&&row.after==='ready');assert.ok(discovered);workspace=reviewReconciliation(projectRow,discovered.fingerprint,{decision:'accepted'}).workspace;assert.equal(workspace.suggestions.some(row=>row.source?.id===sessionId),false);base().prepare("INSERT INTO objectives(uid,project_id,title,status) VALUES(?,?,?,'ready')").run(objectiveUid,projectRow.id,'REC43 — Completed objective');base().prepare("INSERT INTO events(uid,project_id,objective_id,kind,actor_kind,actor,assertion,summary,payload,occurred_at,idempotency_key) VALUES(?,?,?,'work.finished','codex','Codex','system_record','REC43 completed',?,?,?)").run(uid(),projectRow.id,base().prepare('SELECT id FROM objectives WHERE uid=?').get(objectiveUid).id,JSON.stringify({outcome:'completed',verdict:'PASS'}),stamp,`reconciliation-test:${objectiveUid}`);workspace=reconciliationWorkspace(projectRow,{days:2,memoryRoots:[['codex',memory]]});const statusChange=workspace.suggestions.find(row=>row.objective_uid===objectiveUid);assert.equal(statusChange.after,'proven');reviewReconciliation(projectRow,statusChange.fingerprint,{decision:'accepted'});assert.equal(base().prepare('SELECT status FROM objectives WHERE uid=?').get(objectiveUid).status,'proven');assert.equal(base().prepare("SELECT count(*) count FROM events WHERE objective_id=(SELECT id FROM objectives WHERE uid=?) AND source='AI session reconciliation'").get(objectiveUid).count,1)})

test('project opening detects its external pilot and excludes foreign project sessions',()=>{const db=base(),repository=join(dir,'pilot-focus-project'),foreignRepository=join(dir,'foreign-focus-project'),memory=join(dir,'pilot-focus-memory'),projectUid=uid(),foreignUid=uid(),objectiveUid=uid(),pilotSession=uid(),foreignSession=uid(),stamp=new Date().toISOString();mkdirSync(repository);mkdirSync(foreignRepository);mkdirSync(memory);db.prepare("INSERT INTO projects(uid,slug,name,description) VALUES(?,?,?,?)").run(projectUid,'pilot-focus-project','Pilot Focus Project',`Repository: ${repository}`);db.prepare("INSERT INTO projects(uid,slug,name,description) VALUES(?,?,?,?)").run(foreignUid,'foreign-focus-project','Foreign Focus Project',`Repository: ${foreignRepository}`);const projectRow=db.prepare("SELECT * FROM projects WHERE slug='pilot-focus-project'").get();db.prepare("INSERT INTO objectives(uid,project_id,title,status,priority) VALUES(?,?,?,'ready',10)").run(objectiveUid,projectRow.id,'PFX42 — Current pilot mission');writeFileSync(join(memory,`rollout-${pilotSession}.jsonl`),`${JSON.stringify({type:'session_meta',timestamp:stamp,payload:{id:pilotSession,cwd:join(dir,'kenziegames-pilote-pilot-focus-project')}})}\n${JSON.stringify({type:'response_item',timestamp:stamp,payload:{type:'message',role:'assistant',content:[{type:'output_text',text:`CHAPITRE: PFX42 — Current pilot mission\nRACINE: ${repository}`}]}})}\n`);writeFileSync(join(memory,`rollout-${foreignSession}.jsonl`),`${JSON.stringify({type:'session_meta',timestamp:stamp,payload:{id:foreignSession,cwd:foreignRepository}})}\n${JSON.stringify({type:'response_item',timestamp:stamp,payload:{type:'message',role:'assistant',content:[{type:'output_text',text:`CHAPITRE: CFV02 — Foreign work mentioning Pilot Focus Project\nRACINE: ${foreignRepository}`}]}})}\n`);const workspace=reconciliationWorkspace(projectRow,{days:2,memoryRoots:[['codex',memory]]});assert.equal(workspace.sessions.length,1);assert.equal(workspace.summary.pilots,1);assert.equal(workspace.focus.session_id,pilotSession);assert.equal(workspace.focus.title,'Pilote Pilot Focus Project — actif');assert.equal(workspace.focus.objective_uid,objectiveUid);assert.equal(workspace.sessions.some(row=>row.session_id===foreignSession),false)})

