test('conversation sources remain traceable and AI drafts gated until human approval',async()=>{const repository=join(dir,'gdd-project'),memoryRoot=join(dir,'gdd-memory'),projectUid=uid();mkdirSync(repository);mkdirSync(memoryRoot);base().prepare("INSERT INTO projects(uid,slug,name,description,project_type,validation_profile) VALUES(?,?,?,?,'game',?)").run(projectUid,'gdd-project','GDD Project',`Repository: ${repository}`,JSON.stringify({criteria:['Gameplay proof passes.']}));const timestamp=new Date().toISOString(),memoryFile=join(memoryRoot,'session.jsonl');writeFileSync(memoryFile,`${JSON.stringify({type:'user',timestamp,cwd:repository,message:{content:'Build a tactical campaign with persistent choices and a playable standalone result.'}})}\n${JSON.stringify({type:'assistant',timestamp,cwd:repository,message:{content:[{type:'text',text:'Implemented the campaign flow and created a standalone gameplay proof report.'}]}})}\n`);const packet=specificationSourcePacket('gdd-project',{memoryRoots:[['codex',memoryRoot]]});assert.equal(packet.sources.length,2);const question='Which campaign route is canonical?',draft=saveSpecification('gdd-project',{title:'AI GDD',content:{summary:'Tactical campaign.',scope:['Persistent campaign'],deliverables:['Playable standalone'],acceptance_criteria:['Gameplay proof passes.'],chapters:[{key:'vision',title:'Vision',summary:'Persistent choices.',status:'ambiguous',source_ids:['S1'],items:[]}],open_questions:[question],question_answers:[{question,answer:'The integrity route is canonical.',answered_by:'tester'}],sources:packet.sources,status:'draft',generated_from:'ai-conversation-analysis',analysis_provider:'codex'}});assert.equal(draft.status,'draft');assert.equal(draft.content.chapters[0].status,'ambiguous');assert.equal(draft.content.question_answers[0].answer,'The integrity route is canonical.');const history=await(await fetch(`${origin}/api/projects/gdd-project/specification/sources/S1`)).json();assert.equal(history.available,true);assert.equal(history.messages.length,2);assert.equal(history.messages[0].role,'user');assert.equal(specificationGate('gdd-project').blocked_stages.includes('execute'),true);const approved=approveSpecification('gdd-project',{reviewer:'test reviewer'});assert.equal(approved.status,'approved');assert.equal(specificationGate('gdd-project').approved,true)})
test('GDD chapters preserve explicit manual priorities',()=>{const projectUid=uid(),slug='manual-chapters';base().prepare("INSERT INTO projects(uid,slug,name,project_type) VALUES(?,?,?,'game')").run(projectUid,slug,'Manual Chapters');const specification=saveSpecification(slug,{title:'Manual GDD',content:{summary:'Manual structure.',chapters:[{key:'later',title:'Later chapter',summary:'Second.',status:'open',priority:20,items:[]},{key:'first',title:'Priority chapter',summary:'First.',status:'ambiguous',priority:5,items:[]}]}});assert.deepEqual(specification.content.chapters.map(chapter=>chapter.priority),[20,5]);assert.equal(specification.content.chapters[1].title,'Priority chapter')})
test('GDD AI analysis is an asynchronous provider job',async()=>{const fake=join(dir,'fake-codex'),script='#!/bin/sh\ncat >/dev/null\nexit 1\n';writeFileSync(fake,script);chmodSync(fake,0o755);process.env.ORCHESTRATOR_CODEX_COMMAND=fake;try{let response=await fetch(`${origin}/api/projects/test/specification/analyze`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex'})}),job=await response.json();assert.equal(response.status,202,JSON.stringify(job));for(let attempt=0;attempt<300&&job.status==='running';attempt++){await new Promise(resolve=>setTimeout(resolve,20));response=await fetch(`${origin}/api/projects/test/specification/analysis/${job.uid}`);job=await response.json()}assert.equal(job.status,'failed');assert.match(job.error,/code 1/)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})
test('successful GDD reanalysis creates a proposal without changing the current revision',async()=>{const fake=join(dir,'fake-codex-proposal'),candidate={title:'Test specification',summary:'A newly proposed summary.',audience:'Reviewers',context:'New evidence.',scope:['Exercise the controlled workflow.'],non_goals:[],functional_requirements:['Exercise the controlled workflow.'],quality_requirements:[],deliverables:['Verified test result.'],acceptance_criteria:['Automated tests pass.'],constraints:[],risks:[],chapters:[{key:'vision',title:'Vision',summary:'A proposed chapter.',status:'ambiguous',source_ids:[],items:[]}],decisions:[],open_questions:['Should the new summary be accepted?']},script=`#!/bin/sh\nout=""\nwhile [ "$#" -gt 0 ]; do\n  if [ "$1" = "--output-last-message" ]; then shift; out="$1"; fi\n  shift\ndone\ncat >/dev/null\nprintf '%s' '${JSON.stringify(candidate)}' > "$out"\n`;writeFileSync(fake,script);chmodSync(fake,0o755);process.env.ORCHESTRATOR_CODEX_COMMAND=fake;try{const before=await(await fetch(`${origin}/api/projects/test/specification`)).json();let response=await fetch(`${origin}/api/projects/test/specification/analyze`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex',effort:'low'})}),job=await response.json();for(let attempt=0;attempt<300&&job.status==='running';attempt++){await new Promise(resolve=>setTimeout(resolve,20));job=await(await fetch(`${origin}/api/projects/test/specification/analysis/${job.uid}`)).json()}const after=await(await fetch(`${origin}/api/projects/test/specification`)).json();assert.equal(job.status,'completed');assert.equal(job.effort,'low');assert.equal(job.result.kind,'proposal');assert.ok(job.result.proposal.changes.length>0);assert.equal(after.revision,before.revision);assert.equal(after.content.summary,before.content.summary)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})
test('audit-only GDD analysis reports corrections without creating a merge',async()=>{const fake=join(dir,'fake-codex-audit'),candidate={title:'Test specification',summary:'Audit recommendation.',audience:'Reviewers',context:'Evidence.',scope:['Controlled workflow.'],non_goals:[],functional_requirements:['Controlled workflow.'],quality_requirements:[],deliverables:['Verified result.'],acceptance_criteria:['Tests pass.'],constraints:[],risks:[],chapters:[{key:'vision',title:'Vision',summary:'Recommended clarification.',status:'ambiguous',source_ids:[],items:[]}],decisions:[],open_questions:[]},script=`#!/bin/sh\nout=""\nwhile [ "$#" -gt 0 ]; do\n  if [ "$1" = "--output-last-message" ]; then shift; out="$1"; fi\n  shift\ndone\ncat >/dev/null\nprintf '%s' '${JSON.stringify(candidate)}' > "$out"\n`;writeFileSync(fake,script);chmodSync(fake,0o755);process.env.ORCHESTRATOR_CODEX_COMMAND=fake;try{const before=await(await fetch(`${origin}/api/projects/test/specification`)).json();let job=await(await fetch(`${origin}/api/projects/test/specification/analyze`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:'codex',mode:'audit'})})).json();for(let attempt=0;attempt<300&&job.status==='running';attempt++){await new Promise(resolve=>setTimeout(resolve,20));job=await(await fetch(`${origin}/api/projects/test/specification/analysis/${job.uid}`)).json()}const after=await(await fetch(`${origin}/api/projects/test/specification`)).json();assert.equal(job.status,'completed');assert.equal(job.mode,'audit');assert.equal(job.result.kind,'audit');assert.equal(job.result.audit.status,'read-only');assert.ok(job.result.audit.changes.length>0);assert.equal(after.revision,before.revision)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})
test('GDD reanalysis behaves like a reviewed merge without overwriting the baseline',()=>{const projectUid=uid(),slug='merge-project';base().prepare("INSERT INTO projects(uid,slug,name,project_type) VALUES(?,?,?,'game')").run(projectUid,slug,'Merge Project');const baseline=saveSpecification(slug,{title:'Merge GDD',content:{summary:'Stable baseline.',scope:['Campaign'],deliverables:['Playable build'],acceptance_criteria:['Campaign completes.'],chapters:[{key:'vision',title:'Vision',summary:'Original vision.',status:'ambiguous',source_ids:[],items:[]}],status:'approved'}}),jobUid=uid(),candidate={title:'Merge GDD',content:{...baseline.content,summary:'Updated from new evidence.',chapters:[{key:'vision',title:'Vision',summary:'AI rewrite that must be rejected.',status:'closed',source_ids:[],items:[]}],sources:[]}},changes=[{id:'field:summary',scope:'document',field:'summary',kind:'modified',title:'Résumé exécutif',before:baseline.content.summary,after:candidate.content.summary},{id:'chapter:vision',scope:'chapter',field:'chapters',key:'vision',kind:'modified',title:'Vision',before:baseline.content.chapters[0],after:candidate.content.chapters[0],status_before:'ambiguous',status_after:'closed'}],job={uid:jobUid,project:slug,provider:'codex',model:null,status:'completed',phase:'Proposition prête à examiner',created_at:new Date().toISOString(),updated_at:new Date().toISOString(),candidate,result:{kind:'proposal',proposal:{uid:jobUid,project:slug,baseline_revision:baseline.revision,provider:'codex',model:null,created_at:new Date().toISOString(),changes,counts:{total:2,added:0,modified:2,removed:0},status:'pending'}}};base().prepare('INSERT INTO management_settings(key,value,updated_at) VALUES(?,?,?)').run(`specification-analysis:${projectUid}:latest`,JSON.stringify(job),new Date().toISOString());assert.equal(latestSpecificationAnalysis(slug).result.proposal.status,'pending');reviewSpecificationAnalysis(slug,jobUid,{decisions:{'field:summary':'accepted'},finalize:false});assert.equal(latestSpecificationAnalysis(slug).result.proposal.decisions['field:summary'],'accepted');const merged=reviewSpecificationAnalysis(slug,jobUid,{decisions:{'chapter:vision':'rejected'},finalize:true});assert.equal(merged.specification.content.summary,'Updated from new evidence.');assert.equal(merged.specification.content.chapters[0].summary,'Original vision.');assert.equal(merged.specification.status,'draft');assert.equal(merged.specification.revision,baseline.revision+1);assert.equal(merged.job.result.proposal.accepted,1);assert.equal(merged.job.result.proposal.rejected,1)})
test('persistent pilots create observable sessions and preserve execution gates',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/projects/test/pilots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'GDD advisor',role:'advisor',provider:'codex',effort:'high',mission:'Advise on project decisions.'})}),pilot=await response.json();assert.equal(response.status,201,JSON.stringify(pilot));assert.equal(pilot.role,'coordinator');assert.equal(pilot.default_agent_role,'researcher');assert.equal(pilot.permission_profile,'read_only');assert.equal(pilot.effort,'high');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/launch`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({request:'Find the next ambiguity.'})});const launched=await response.json();assert.equal(response.status,201,JSON.stringify(launched));assert.equal(launched.session.metadata.pilot_uid,pilot.uid);assert.equal(launched.session.metadata.pilot_role,'coordinator');assert.equal(launched.session.metadata.permission_profile,'read_only');assert.equal(launched.session.metadata.launch_options.disable_tools,undefined);assert.equal(launched.session.metadata.launch_options.effort,'high');assert.equal(launched.agent.metadata.pilot_parent_session_uid,launched.session.uid);assert.equal(launched.agent.metadata.pilot_agent_role,'researcher');response=await fetch(`${origin}/api/projects/test/pilots`);const listed=await response.json();assert.equal(listed.pilots[0].run_count,1);base().prepare("INSERT INTO projects(uid,slug,name) VALUES(?,?,?)").run(uid(),'pilot-unapproved','Pilot Unapproved');response=await fetch(`${origin}/api/projects/pilot-unapproved/pilots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Executor',role:'executor',provider:'codex',mission:'Execute approved work.'})});const executor=await response.json();response=await fetch(`${origin}/api/projects/pilot-unapproved/pilots/${executor.uid}/launch`,{method:'POST'});assert.equal(response.status,409)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})

