test('team workspace links people machines projects and existing external tickets',async()=>{base().prepare("INSERT OR IGNORE INTO workspace_projects(workspace_id,project_id) SELECT w.id,p.id FROM workspaces w,projects p WHERE w.status='active' AND p.slug='test'").run();let response=await fetch(`${origin}/api/team`),team=await response.json();const initialMembers=team.summary.members,initialItems=team.summary.external_items;assert.equal(response.status,200);assert.equal(team.execution,false);assert.equal(team.summary.projects>=1,true);response=await fetch(`${origin}/api/team/members`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({display_name:'Ada Dev',email:'ada@example.test',external_ids:{clickup:'42'}})});const member=await response.json();assert.equal(response.status,201);response=await fetch(`${origin}/api/team/machines/mac-team`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({member_uid:member.uid,label:'Ada Mac',platform:'darwin'})});assert.equal(response.status,200);response=await fetch(`${origin}/api/team/projects/test/members/${member.uid}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({role:'contributor'})});assert.equal(response.status,200);response=await fetch(`${origin}/api/team/external-items`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({project:'test',provider:'clickup',external_id:'task-existing-1',title:'Existing team ticket',status:'in progress',url:'https://app.clickup.com/t/task-existing-1',pass_ref:'pass-7',assignee_uid:member.uid})});const item=await response.json();assert.equal(response.status,201);assert.equal(item.assignee_name,'Ada Dev');assert.equal(item.pass_ref,'pass-7');response=await fetch(`${origin}/api/team/onboarding/test`);const bundle=await response.json();assert.equal(bundle.format,'orchestrator-team-onboarding');assert.equal(bundle.execution,false);assert.ok(bundle.setup.some(line=>line.includes('orchestrator team join')));assert.ok(Array.isArray(bundle.chapters));assert.ok(Array.isArray(bundle.objectives));assert.equal(bundle.external_items.some(row=>row.external_id==='task-existing-1'),true);response=await fetch(`${origin}/api/team/onboarding/import`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(bundle)});const imported=await response.json();assert.equal(response.status,201);assert.equal(imported.external_items,bundle.external_items.length);team=await(await fetch(`${origin}/api/team`)).json();assert.equal(team.summary.members,initialMembers+1);assert.equal(team.summary.external_items,initialItems+1);assert.equal(team.members.some(row=>row.uid===member.uid&&row.display_name==='Ada Dev'),true);assert.equal(team.external_items.some(row=>row.provider==='clickup'&&row.external_id==='task-existing-1'),true);assert.equal(team.machines.find(row=>row.machine_key==='mac-team').member_uid,member.uid)})
test('historical recovery finds only explicit proof-like conversation paths',()=>{const repository=join(dir,'recovery-project'),memoryRoot=join(dir,'recovery-memory'),proof=join(repository,'Review','pass-7','evidence-screenshot.png'),source=join(repository,'src','normal.js'),foreign=join(dir,'other-project','Review','foreign-proof.png');mkdirSync(join(repository,'Review','pass-7'),{recursive:true});mkdirSync(join(repository,'src'),{recursive:true});mkdirSync(join(dir,'other-project','Review'),{recursive:true});mkdirSync(memoryRoot,{recursive:true});writeFileSync(proof,'image proof');writeFileSync(source,'source');writeFileSync(foreign,'foreign proof');const recoveryProject={id:base().prepare("SELECT id FROM projects WHERE slug='test'").get().id,slug:'test',name:'Test',description:`Repository: ${repository}`};writeFileSync(join(memoryRoot,'session.jsonl'),`${JSON.stringify({timestamp:new Date().toISOString(),cwd:repository,message:`Proof saved at ${proof}; edited ${source}; unrelated ${foreign}`})}\n`);const result=recoverLocalEvidence(recoveryProject,{since:'2000-01-01T00:00:00Z',memoryRoots:[['codex',memoryRoot]]});assert.equal(result.sessions,1,JSON.stringify(result));assert.equal(result.candidates.length,1,JSON.stringify(result));assert.equal(result.candidates[0].path,proof);assert.equal(result.candidates[0].status,'available');assert.match(result.candidates[0].sha256,/^[a-f0-9]{64}$/);assert.equal(result.candidates[0].pass_ref,'7')})
