test('temporary Internet access protects every API before one-time pairing',async()=>{process.env.ORCHESTRATOR_REMOTE_TEST_URL='https://safe-test.trycloudflare.com';try{let response=await fetch(`${origin}/api/remote/access/start`,{method:'POST'}),status=await response.json();assert.equal(response.status,202,JSON.stringify(status));assert.equal(status.phase,'online');assert.match(status.pairing_code,/^\d{6}$/);const remoteHeaders={'x-forwarded-host':'safe-test.trycloudflare.com','x-forwarded-for':'203.0.113.9','x-forwarded-proto':'https',origin:'https://safe-test.trycloudflare.com'};response=await fetch(`${origin}/api/remote/access/bootstrap`,{headers:remoteHeaders});let data=await response.json();assert.equal(response.status,200,JSON.stringify(data));assert.deepEqual({remote:data.remote,authenticated:data.authenticated},{remote:true,authenticated:false});response=await fetch(`${origin}/api/projects`,{headers:remoteHeaders});assert.equal(response.status,401);response=await fetch(`${origin}/api/remote/access/pair`,{method:'POST',headers:{...remoteHeaders,'content-type':'application/json'},body:JSON.stringify({code:status.pairing_code,label:'Test phone'})});data=await response.json();assert.equal(response.status,201,JSON.stringify(data));assert.match(data.token,/^orch_[a-f0-9]{64}$/);assert.match(response.headers.get('set-cookie')||'',/orchestrator_access=/);response=await fetch(`${origin}/api/projects`,{headers:{...remoteHeaders,authorization:`Bearer ${data.token}`}});assert.equal(response.status,200);assert.ok(Array.isArray(await response.json()));response=await fetch(`${origin}/api/remote/access/code`,{method:'POST',headers:{...remoteHeaders,authorization:`Bearer ${data.token}`}});assert.equal(response.status,403)}finally{delete process.env.ORCHESTRATOR_REMOTE_TEST_URL;await fetch(`${origin}/api/remote/access/stop`,{method:'POST'})}})
test('system health reports database integrity without mutation',async()=>{const before=base().prepare('SELECT count(*) n FROM events').get().n,response=await fetch(`${origin}/api/system/health`),data=await response.json();assert.equal(response.status,200);assert.equal(data.ok,true);assert.equal(data.execution,false);assert.equal(data.database.integrity,'ok');assert.equal(data.database.foreign_key_violations,0);assert.ok(Number.isFinite(data.database.bytes));assert.ok(Array.isArray(data.backups));assert.equal(base().prepare('SELECT count(*) n FROM events').get().n,before)})
test('a closed pass cannot be closed twice and exposes its verified workflow result',async()=>{const objective=base().prepare("SELECT uid FROM objectives WHERE title='Linked terminal objective'").get(),session=base().prepare("SELECT uid,metadata FROM terminal_sessions WHERE title='Linked test terminal' ORDER BY id DESC").get(),metadata=JSON.parse(session.metadata);assert.equal(metadata.report_status,'verified');assert.ok(metadata.pass_closed_at);const response=await fetch(`${origin}/api/projects/test/passes/${metadata.pass_uid}/close`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objective_uid:objective.uid})}),result=await response.json();assert.equal(response.status,409,JSON.stringify(result));assert.equal(result.closed,true);assert.match(result.event_uid,/^[a-f0-9-]+$/)})

test('pilot rooms group child agents and persist shared messages',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/projects/test/pilots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Room pilot',role:'coordinator',autonomy_mode:'auto',provider:'codex',mission:'Coordinate a bounded read-only test.'})}),pilot=await response.json();assert.equal(pilot.autonomy_mode,'auto');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({autonomy_mode:'semi'})});pilot=await response.json();assert.equal(pilot.autonomy_mode,'semi');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/launch`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});const launched=await response.json();assert.equal(response.status,201,JSON.stringify(launched));assert.equal(launched.pilot.role,'coordinator');assert.equal(launched.pilot.permission_profile,'read_only');assert.equal(launched.session.metadata.pilot_role,'coordinator');assert.equal(launched.session.metadata.permission_profile,'read_only');assert.equal(launched.session.metadata.pilot_parent_session_uid,null);response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}/agents`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Reviewer',role:'reviewer',provider:'codex',mission:'Review the pilot checkpoint.'})});const agent=await response.json();assert.equal(response.status,201,JSON.stringify(agent));assert.equal(agent.metadata.pilot_parent_session_uid,launched.session.uid);assert.equal(agent.metadata.pilot_run_uid,launched.run_uid);response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}/messages`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sender:'Tester',target:'all',content:'Share this checkpoint.'})});const sent=await response.json();assert.equal(response.status,201,JSON.stringify(sent));assert.equal(sent.message.content,'Share this checkpoint.');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}`);const room=await response.json();assert.equal(room.pilot.autonomy_mode,'semi');assert.equal(room.sessions.length,3);assert.deepEqual(new Set(room.sessions.map(row=>row.metadata.pilot_role)),new Set(['coordinator','researcher','reviewer']));assert.equal(room.messages.some(message=>message.sender==='Tester'&&message.content==='Share this checkpoint.'),true);assert.equal(room.insights.length,3);assert.ok(room.insights.every(item=>Object.hasOwn(item,'decision_request')))}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})

test('approved pilot actions are delegated without elevating the coordinator',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/projects/test/pilots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Delegation guard pilot',role:'executor',autonomy_mode:'manual',provider:'codex',permission_profile:'workspace_guarded',mission:'Coordinate an approved action.'})}),pilot=await response.json();assert.equal(response.status,201,JSON.stringify(pilot));assert.equal(pilot.role,'coordinator');assert.equal(pilot.permission_profile,'read_only');assert.equal(pilot.default_agent_role,'executor');assert.equal(pilot.worker_permission_profile,'workspace_guarded');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/launch`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});const launched=await response.json();assert.equal(response.status,201,JSON.stringify(launched));assert.equal(launched.agent,null);assert.equal(launched.session.metadata.pilot_role,'coordinator');assert.equal(launched.session.metadata.permission_profile,'read_only');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}/delegate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Approved executor',role:'executor',permission_profile:'workspace_guarded',mission:'Execute only the approved bounded action.'})});const delegated=await response.json();assert.equal(response.status,201,JSON.stringify(delegated));assert.equal(delegated.root.uid,launched.session.uid);assert.equal(delegated.root.metadata.permission_profile,'read_only');assert.equal(delegated.session.metadata.pilot_parent_session_uid,launched.session.uid);assert.equal(delegated.session.metadata.pilot_agent_role,'executor');assert.equal(delegated.session.metadata.permission_profile,'workspace_guarded');assert.equal(delegated.message.kind,'delegation');response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}`);const room=await response.json();assert.equal(room.sessions.filter(row=>row.metadata.pilot_role==='coordinator').length,1);assert.equal(room.sessions.find(row=>row.metadata.pilot_role==='coordinator').metadata.permission_profile,'read_only');assert.equal(room.messages.some(message=>message.uid===delegated.message.uid&&message.target===delegated.session.uid),true)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})

test('pilot context rotation starts a fresh native session with a bounded durable handoff',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/sh';try{let response=await fetch(`${origin}/api/projects/test/pilots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Rotating pilot',role:'coordinator',provider:'codex',mission:'Coordinate without carrying an unlimited transcript.',rotation_mode:'auto',rotation_threshold_tokens:40000})}),pilot=await response.json();assert.equal(pilot.rotation_mode,'auto');assert.equal(pilot.rotation_threshold_tokens,40000);response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/launch`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});const launched=await response.json();response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}/messages`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sender:'Vous',target:'all',content:'Décision humaine : conserver le périmètre actuel.'})});assert.equal(response.status,201);response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}/rotate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({reason:'test_handoff'})});const rotated=await response.json();assert.equal(response.status,201,JSON.stringify(rotated));assert.notEqual(rotated.session.uid,launched.session.uid);assert.equal(rotated.session.metadata.pilot_run_uid,launched.run_uid);assert.equal(rotated.session.metadata.rotated_from_uid,launched.session.uid);assert.equal(rotated.session.metadata.rotation_index,1);assert.equal(rotated.session.metadata.launch_options.resume_mode,'new');assert.match(rotated.handoff.human_decisions[0].decision,/conserver le périmètre/);assert.equal(rotated.context_rotation.estimated_tokens,0)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})

test('completed pilot agents return their checkpoint to the pilot room',async()=>{process.env.ORCHESTRATOR_CODEX_COMMAND='/bin/echo';try{let response=await fetch(`${origin}/api/projects/test/pilots`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Checkpoint pilot',role:'coordinator',provider:'codex',mission:'Receive a bounded checkpoint.'})}),pilot=await response.json();response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/launch`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});const launched=await response.json();response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}/agents`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Echo reviewer',role:'reviewer',provider:'codex',mission:'Return a checkpoint.'})});assert.equal(response.status,201);let room;for(let attempt=0;attempt<100;attempt++){await new Promise(resolve=>setTimeout(resolve,10));response=await fetch(`${origin}/api/projects/test/pilots/${pilot.uid}/rooms/${launched.run_uid}`);room=await response.json();if(room.messages.some(message=>message.sender==='Echo reviewer'))break}const checkpoint=room.messages.find(message=>message.sender==='Echo reviewer');assert.ok(checkpoint);assert.match(checkpoint.content,/Checkpoint automatique du sous-agent/)}finally{delete process.env.ORCHESTRATOR_CODEX_COMMAND}})

test('events are idempotent and append-only',async()=>{
  const before=base().prepare('SELECT count(*) n FROM events').get().n
  const body={project:'test',kind:'event.recorded',actor_kind:'codex',actor:'Codex',assertion:'agent_statement',summary:'Observed state'}
  const first=await fetch(`${origin}/api/ingest`,{method:'POST',headers:{'content-type':'application/json','Idempotency-Key':'same'},body:JSON.stringify(body)})
  const second=await fetch(`${origin}/api/ingest`,{method:'POST',headers:{'content-type':'application/json','Idempotency-Key':'same'},body:JSON.stringify(body)})
  assert.equal(first.status,201); assert.equal(second.status,200); assert.equal(base().prepare('SELECT count(*) n FROM events').get().n,before+1)
  assert.throws(()=>base().prepare('UPDATE events SET summary=?').run('changed'),/append-only/)
})
test('project tracking commands are portable, passive and enforce disable',async()=>{const root=join(dir,'cli-project');mkdirSync(root);let state=setTracking(true,{root,project:'cli-project',name:'CLI Project'});assert.equal(state.enabled,true);assert.equal(readTracking(root).evidence_mode,'declared-only');assert.equal(trackingStatus(root).project.status,'active');const fixture=join(root,'proof.txt');writeFileSync(fixture,'declared proof');const proof=await addDeclaredEvidence(fixture,{root,endpoint:origin,actorKind:'claude',actor:'Claude',type:'test'});assert.equal(proof.bytes,14);assert.match(proof.sha256,/^[a-f0-9]{64}$/);let observed=await recordObservation({kind:'cost.recorded',actor_kind:'codex',actor:'Codex',assertion:'measured_fact',summary:'Declared usage',payload:{amount:0.25,currency:'USD',known:true,total_tokens:100,cost_basis:'measured'}},{root,endpoint:origin});assert.equal(observed.duplicate,false);observed=await recordObservation({kind:'cost.recorded',actor_kind:'codex',actor:'Codex',assertion:'measured_fact',summary:'Declared usage',payload:{amount:0.25,currency:'USD',known:true,total_tokens:100,cost_basis:'measured'}},{root,endpoint:origin});assert.equal(observed.duplicate,true);await recordObservation({kind:'cost.recorded',actor_kind:'codex',actor:'Codex',assertion:'agent_statement',summary:'Estimated usage',payload:{model:'gpt-5.6-sol',input_tokens:1_000_000,output_tokens:0}},{root,endpoint:origin});const estimate=base().prepare("SELECT c.amount,c.known,e.payload FROM costs c JOIN events e ON e.id=c.event_id WHERE e.summary='Estimated usage'").get();assert.equal(estimate.amount,5);assert.equal(estimate.known,1);assert.equal(JSON.parse(estimate.payload).cost_basis,'estimated');state=setTracking(false,{root});assert.equal(state.enabled,false);assert.equal(trackingStatus(root).enabled,false);await assert.rejects(addDeclaredEvidence(fixture,{root,endpoint:origin}),/disabled/);await assert.rejects(recordObservation({kind:'event.recorded'},{root,endpoint:origin}),/disabled/);const response=await fetch(`${origin}/api/ingest`,{method:'POST',headers:{'content-type':'application/json','Idempotency-Key':'disabled-direct'},body:JSON.stringify({project:'cli-project',kind:'event.recorded',actor_kind:'codex',actor:'Codex',assertion:'agent_statement',summary:'Should be refused'})});assert.equal(response.status,409);setTracking(true,{root});assert.equal(trackingStatus(root).enabled,true)})
test('tracking is central and ignores foreign repository configuration',()=>{const root=join(dir,'extended-tracking-project');mkdirSync(root);const path=join(root,'.orchestrator.json');writeFileSync(path,JSON.stringify({format:'another-tool',enabled:true}));setTracking(true,{root,project:'extended-tracking',name:'Extended Tracking',enforcementMode:'strict'});const updated=readTracking(root);assert.equal(updated.configuration,'central');assert.equal(updated.enforcement_mode,'strict');assert.equal(existsSync(path),true);assert.equal(JSON.parse(readFileSync(path,'utf8')).format,'another-tool')})
test('external Git hooks preserve existing hooks and report passive state',async()=>{const root=join(dir,'hook-project'),hooks=join(root,'.git','hooks');mkdirSync(hooks,{recursive:true});writeFileSync(join(hooks,'post-commit'),'#!/bin/sh\nprintf existing-hook\n');setTracking(true,{root,project:'hook-project',name:'Hook Project'});const installed=installGitHooks({root,command:'/usr/local/bin/orchestrator'});assert.equal(installed.installed,true);assert.equal(installed.hooks.length,6);assert.equal(installed.hooks.some(row=>row.name==='pre-push'),true);assert.match(readFileSync(join(hooks,'post-commit'),'utf8'),/existing-hook/);assert.match(readFileSync(join(hooks,'orchestrator-observe'),'utf8'),/hook git/);const observation=await recordGitHook({root,endpoint:origin,environment:{ORCHESTRATOR_HOOK_TRIGGER:'post-commit',ORCHESTRATOR_HOOK_BRANCH:'main',ORCHESTRATOR_HOOK_HEAD:'abc123',ORCHESTRATOR_HOOK_DIRTY:'false'}});assert.equal(observation.duplicate,false);const event=base().prepare("SELECT payload FROM events WHERE summary='Git state observed after post-commit'").get();assert.equal(JSON.parse(event.payload).head_commit,'abc123');const removed=uninstallGitHooks({root});assert.equal(removed.installed,false);assert.equal(removed.helper_removed,true);assert.match(readFileSync(join(hooks,'post-commit'),'utf8'),/existing-hook/);assert.doesNotMatch(readFileSync(join(hooks,'post-commit'),'utf8'),/orchestrator-observer/);assert.equal(gitHookStatus(root).installed,false)})
test('passive follower batches local repository changes without executing work',async()=>{const root=join(dir,'followed-project');mkdirSync(root);setTracking(true,{root,project:'followed-project',name:'Followed Project'});try{const observed=new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('Follower did not observe the change.')),2000);startPassiveFollowers({debounceMs:40,rescanMs:500,onBatch:batch=>{if(batch.project.slug==='followed-project'){clearTimeout(timeout);resolve(batch)}}});writeFileSync(join(root,'change.txt'),'observed')});const batch=await observed;assert.deepEqual(batch.paths,['change.txt']);assert.equal(batch.project.slug,'followed-project')}finally{stopPassiveFollowers()}})
