test('evidence verification reports and persists verified, modified and missing files',async()=>{const fixture=join(dir,'proof.txt'),content='measured output';writeFileSync(fixture,content);const hash=createHash('sha256').update(content).digest('hex'),body={project:'test',kind:'evidence.recorded',actor_kind:'codex',actor:'Codex',assertion:'measured_fact',summary:'Verified file',payload:{label:'proof',type:'test',origin:'test',locator_kind:'path',path:fixture,status:'available',sha256:hash,bytes:content.length}};const created=await fetch(`${origin}/api/ingest`,{method:'POST',headers:{'content-type':'application/json','Idempotency-Key':'verified-proof'},body:JSON.stringify(body)}),uid=(await created.json()).events[0].event.id,proof=base().prepare('SELECT uid FROM evidence_manifests WHERE event_id=?').get(uid);let result=await(await fetch(`${origin}/api/evidence/${proof.uid}/verify`,{method:'POST'})).json();assert.equal(result.verification,'verified');assert.ok(result.verified_at);let stored=(await(await fetch(`${origin}/api/projects/test/evidence`)).json()).find(item=>item.uid===proof.uid);assert.equal(stored.verification,'verified');assert.ok(stored.verified_at);writeFileSync(fixture,'changed');result=await(await fetch(`${origin}/api/evidence/${proof.uid}/verify`)).json();assert.equal(result.verification,'modified');rmSync(fixture);result=await(await fetch(`${origin}/api/evidence/${proof.uid}/verify`)).json();assert.equal(result.verification,'missing');stored=(await(await fetch(`${origin}/api/projects/test/evidence`)).json()).find(item=>item.uid===proof.uid);assert.equal(stored.verification,'missing')})
